class Solution {
    private lateinit var graph:List<MutableList<Int>>;
    private val answer=mutableListOf<List<Int>>();
    private lateinit var discovery:IntArray;
    private lateinit var low:IntArray;
    private var time=1;
    fun criticalConnections(n:Int,connections:List<List<Int>>):List<List<Int>>{
        graph=List(n){
            mutableListOf()
        };
        for(edge in connections){
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0])
        };
        answer.clear();
        discovery=IntArray(n);
        low=IntArray(n);
        time=1;
        dfs(0,-1);
        return answer
    };
    private fun dfs(node:Int,parent:Int){
        discovery[node]=time;
        low[node]=time++;
        for(next in graph[node]){
            if(next==parent)continue;
            if(discovery[next]==0){
                dfs(next,node);
                low[node]=minOf(low[node],low[next]);
                if(low[next]>discovery[node])answer.add(listOf(node,next))
            }else low[node]=minOf(low[node],discovery[next])
        }
    }
}

